mapper.select:
SELECT message_id, conversation_id, sender_id, content, status, client_message_id, create_time
FROM messages
WHERE conversation_id = #{conversationId}
  AND status = #{sentStatus}

    AND (create_time < #{cursorSendTime}
         OR (create_time = #{cursorSendTime} AND message_id < #{cursorMessageId}))

ORDER BY create_time DESC, message_id DESC
LIMIT #{limit}
